class GradientTests(unittest.TestCase):
    def test_origin(self):
        loss,gw,gb=loss_and_grad(0,0,2,1)
        self.assertAlmostEqual(loss,math.log(2)); self.assertAlmostEqual(gw,-1); self.assertAlmostEqual(gb,-.5)
    def test_zero_feature(self):
        self.assertEqual(loss_and_grad(7,.2,0,0)[1],0)
    def test_numerical_gradient(self):
        for w,b,x,y in [(1,.2,3,1),(-2,.4,-.5,0),(.4,-1,2,0)]:
            loss,gw,gb=loss_and_grad(w,b,x,y)
            self.assertAlmostEqual(gw,central_difference(lambda t:loss_and_grad(t,b,x,y)[0],w),places=6)
            self.assertAlmostEqual(gb,central_difference(lambda t:loss_and_grad(w,t,x,y)[0],b),places=6)
    def test_extreme_wrong_predictions(self):
        for w,y,grad in [(1000,0,1),(-1000,1,-1)]:
            loss,gw,gb=loss_and_grad(w,0,1,y)
            self.assertTrue(math.isfinite(loss));self.assertAlmostEqual(loss,1000);self.assertAlmostEqual(gb,grad)
    def test_extreme_right_predictions(self):
        for w,y in [(1000,1),(-1000,0)]:
            loss,gw,gb=loss_and_grad(w,0,1,y)
            self.assertTrue(math.isfinite(loss));self.assertAlmostEqual(loss,0);self.assertAlmostEqual(gw,0)
    def test_difference_and_validation(self):
        self.assertAlmostEqual(central_difference(lambda t:t*t,3),6,places=7)
        with self.assertRaises(ValueError):central_difference(lambda t:t,1,0)
        with self.assertRaises(ValueError):loss_and_grad(0,0,1,.5)

