class RegressionTests(unittest.TestCase):
    def test_mse(self):
        self.assertAlmostEqual(mse([(0,1),(1,3)],0,0),5)
        self.assertEqual(mse([(0,1),(1,3)],2,1),0)
    def test_one_update(self):
        r=train([(2,3)],.1,1)
        self.assertAlmostEqual(r['w'],1.2);self.assertAlmostEqual(r['b'],.6)
        self.assertEqual(len(r['losses']),2);self.assertAlmostEqual(r['losses'][-1],0)
    def test_two_ordered_updates(self):
        r=train([(1,2),(2,0)],.1,1)
        self.assertAlmostEqual(r['w'],-.08);self.assertAlmostEqual(r['b'],.16)
    def test_no_updates(self):
        for lr,epochs in [(0,3),(.1,0)]:
            r=train([(1,2)],lr,epochs)
            self.assertEqual((r['w'],r['b']),(0,0));self.assertEqual(r['losses'],[4]*(epochs+1))
    def test_real_learning(self):
        data=[(x,2*x+1) for x in [-2,-1,0,1,2]]
        r=train(data,.02,200)
        self.assertLess(r['losses'][-1],1e-8);self.assertAlmostEqual(r['w'],2,places=4);self.assertAlmostEqual(r['b'],1,places=4)
        self.assertAlmostEqual(r['losses'][-1],mse(data,r['w'],r['b']))
    def test_invalid(self):
        for data,lr,epochs in [([],.1,1),([(1,2)],-.1,1),([(1,2)],.1,-1),([(1,2)],.1,1.5)]:
            with self.assertRaises(ValueError):train(data,lr,epochs)
        with self.assertRaises(ValueError):mse([],0,0)

