import math
import unittest
from solution import *

class PolicyTests(unittest.TestCase):
    def test_uniform(self):
        self.assertEqual(softmax([0,0]),[.5,.5]);self.assertAlmostEqual(log_prob([0,0],1),-math.log(2))
    def test_shift(self):
        for a,b in zip(softmax([1,2,3]),softmax([1001,1002,1003])):self.assertAlmostEqual(a,b)
    def test_extreme_log_probability(self):
        self.assertAlmostEqual(log_prob([1000,-1000],1),-2000);self.assertTrue(math.isfinite(log_prob([1000,-1000],1)))
    def test_gradient_sign(self):
        loss,g=reinforce_loss_grad([0,0],0,2)
        self.assertAlmostEqual(loss,2*math.log(2));self.assertEqual(g,[-1,1]);self.assertAlmostEqual(sum(g),0)
        self.assertGreater(softmax([-0.1*v for v in g])[0],.5)
    def test_gradient_finite_differences(self):
        z=[.2,-.7,1.1];eps=1e-5
        for adv in [-2,0,3]:
            _,g=reinforce_loss_grad(z,1,adv)
            for j in range(3):
                p=z.copy();m=z.copy();p[j]+=eps;m[j]-=eps
                expected=(-adv*log_prob(p,1)+adv*log_prob(m,1))/(2*eps)
                self.assertAlmostEqual(g[j],expected,places=6)
    def test_single_action_and_validation(self):
        self.assertEqual(softmax([9]),[1]);self.assertEqual(reinforce_loss_grad([9],0,5),(0,[0]))
        for logits,action in [([],0),([1],1),([1],-.1)]:
            with self.assertRaises(ValueError):log_prob(logits,action)

if __name__ == '__main__':
    unittest.main()

