        q,s=quantize_rows([[-2,0,2]])
        self.assertEqual(q,[[-127,0,127]]);self.assertAlmostEqual(s[0],2/127)
        self.assertEqual(dequantize_rows(q,s),[[-2,0,2]])
    def test_zero_row(self):
        q,s=quantize_rows([[0,0]])
        self.assertEqual((q,s),([[0,0]],[1]));self.assertEqual(quantized_matvec(q,s,[4,-8]),[0])
    def test_rows_have_independent_scales(self):
        q,s=quantize_rows([[1,-1],[100,-100]])
        self.assertEqual(q,[[127,-127],[127,-127]]);self.assertAlmostEqual(s[1]/s[0],100)
    def test_ties_to_even(self):
        q,s=quantize_rows([[127,.5,1.5,2.5]])
        self.assertEqual(q,[[127,0,2,2]])
    def test_matvec_and_bound(self):
        w=[[.13,-.47,.8],[3.1,.2,-1.7]];x=[2,-3,.1]
        q,s=quantize_rows(w);out=quantized_matvec(q,s,x)
        for row,scale,y in zip(w,s,out):
            baseline=sum(a*b for a,b in zip(row,x))
