    def test_validation(self):
        for w in [[],[[]],[[1],[2,3]]]:
            with self.assertRaises(ValueError):quantize_rows(w)
        for q,s in [([[128]],[1]),([[.5]],[1]),([[1]],[]),([[1]],[0])]:
