        p=[0,0];a=[3,-4];self.assertEqual(step(p,a,.5,2),[1,-1]);self.assertEqual(p,[0,0]);self.assertEqual(a,[3,-4])
    def test_unsaturated_step(self):self.assertEqual(step([1,2],[.2,-.4],.5),[1.1,1.8])
    def test_trajectory_contract(self):
        path=rollout([0,0],[1,0],1,2,.5)
        self.assertEqual(path,[[0,0],[.5,0],[.75,0]]);self.assertIsNot(path[0],path[1])
    def test_zero_steps_and_gain(self):
        self.assertEqual(rollout([1,2],[3,4],1,0),[[1,2]])
        self.assertEqual(rollout([1,2],[3,4],0,2),[[1,2],[1,2],[1,2]])
    def test_held_out_baseline(self):
        held_out=[[.7,-.3],[-.6,.4],[.2,.8]]
        good=evaluate(held_out,2,80);bad=evaluate(held_out,0,80)
        self.assertEqual(good['success_rate'],1);self.assertEqual(bad['success_rate'],0)
        self.assertLess(good['mean_final_distance'],1e-6);self.assertGreater(good['mean_path_length'],0)
